package co.sena.academic.adapter.in.rest.exception; import co.sena.academic.domain.exception.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestControllerAdvice public class LearningOutcomeExceptionHandler {@ExceptionHandler(LearningOutcomeNotFoundException.class) ResponseEntity<ApiErrorResponse> notFound(RuntimeException e){return ResponseEntity.status(HttpStatus.NOT_FOUND).body(ApiErrorResponse.of("ACAD_LEARNING_OUTCOME_NOT_FOUND",e.getMessage()));}@ExceptionHandler(LearningOutcomeCodeAlreadyExistsException.class) ResponseEntity<ApiErrorResponse> duplicate(RuntimeException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(ApiErrorResponse.of("ACAD_LEARNING_OUTCOME_CODE_ALREADY_EXISTS",e.getMessage()));}}
